{
  "packet_id": "H6-T02-1",
  "claim_id": "C047",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C047",
    "value": "If endpoints or measurements cannot be established, evidence must be gathered before selecting a code rollback.",
    "scope": "Rollback-selection restriction in the fallback instrumentation branch.",
    "provenance": {
      "refs": [
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P027 explicitly makes evidence gathering precede code rollback selection when endpoints or measurements cannot be established."
    }
  },
  "signal_basis": {
    "component_id": "C047_SIGNAL",
    "value": "Attempts to establish good and bad revision endpoints or validate comparable export timing do not establish the endpoints or measurements needed for revision attribution.",
    "scope": "The failure condition triggering the fallback instrumentation branch.",
    "provenance": {
      "refs": [
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P007",
          "role": "CONTEXT"
        },
        {
          "source_id": "P008",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P027 supplies the fallback condition; P007 and P008 identify the endpoints and measurement comparability at issue."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C047_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is a supported evidence-gathering restriction, not an inference awaiting a specific empirical relation."
    }
  },
  "rationale": "Failure to establish revision endpoints or comparable measurements leaves this investigation without an adequate basis for selecting a code rollback. Gathering evidence first is warranted within the stated fallback branch. The claim does not assert that gathering evidence alone will justify a particular rollback.",
  "uncertainty": "The packet does not establish which rollback, if any, later evidence would justify; that lies outside this claim.",
  "anomalies": []
}
